403	+export const ZimmTable = ({
404	+  columns,
405	+  columnSpan = 1,
406	+  subColumns,
407	+  rows,
408	+  labelless = false,
409	+  bordered = false,
410	+}: ZimmTableProps) => {
411	+  const variant = labelless && bordered ? 'bordered' : labelless ? 'labelless' : 'standard';
412	+  const styles = useMultiStyleConfig(ZIMM_TABLE_RECIPE, { variant });
413	+
414	+  if (labelless && bordered) {
415	+    // Pair consecutive rows into [headerRow, valueRow] groups, separated by a visual gap.
416	+    const groups: ZimmTableRow[][] = [];
417	+    for (let i = 0; i < rows.length; i += 2) groups.push(rows.slice(i, i + 2));
418	+    // Derive total column count from the maximum span sum across all rows.
419	+    const totalCols = Math.max(...rows.map((row) => (row.spans ?? row.cells.map(() => 1)).reduce((a, b) => a + b, 0)));
420	+    return (
421	+      <chakra.table __css={styles.table}>
