425	+          ))}
426	+        </chakra.colgroup>
427	+        <chakra.tbody>
428	+          {groups.map((group, gi) => (
429	+            <React.Fragment key={gi}>
430	+              {gi > 0 && (
431	+                <chakra.tr>
432	+                  <chakra.td __css={styles.spacerTd} colSpan={totalCols} />
433	+                </chakra.tr>
434	+              )}
435	+              {group.map((row, ri) =>
436	+                row.isHeader ? (
437	+                  <chakra.tr key={ri}>
438	+                    {row.cells.map((cell, j) => (
439	+                      <chakra.th
440	+                        key={j}
441	+                        __css={styles.th}
442	+                        colSpan={row.spans?.[j] ?? 1}
443	+                        textAlign="center"
444	+                        borderBottom={BORDER_FOCUS}
445	+                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
446	+                      >
447	+                        {cell}
448	+                      </chakra.th>
449	+                    ))}
450	+                  </chakra.tr>
451	+                ) : (
452	+                  <chakra.tr key={ri}>
453	+                    {row.cells.map((cell, j) => (
454	+                      <chakra.td
455	+                        key={j}
456	+                        __css={styles.td}
457	+                        colSpan={row.spans?.[j] ?? 1}
458	+                        textAlign="center"
459	+                        borderBottom={BORDER_SECONDARY}
460	+                        borderLeft={j > 0 ? BORDER_SECONDARY : undefined}
461	+                      >
462	+                        {cell}
463	+                      </chakra.td>
464	+                    ))}
465	+                  </chakra.tr>
466	+                ),
467	+              )}
468	+            </React.Fragment>
469	+          ))}
470	+        </chakra.tbody>
471	+      </chakra.table>
472	+    );
473	+  }
474	+
475	+  if (labelless) {
476	+    return (
477	+      <chakra.table __css={styles.table}>
478	+        <chakra.tbody>
479	+          {rows.map((row, i) =>
480	+            row.isHeader ? (
481	+              <chakra.tr key={i} bg={i % 2 !== 0 ? 'var(--zimm-color-bg-02)' : undefined}>
