822	+import { useMemo } from 'react';
823	+import { CONTENTFUL_FALLBACK_LOCALE } from '../config/contentful';
824	+import { useContentfulEntries } from './useContentful';
825	+import type { SizeGuideEntry } from '../types/contentful';
826	+
827	+/**
828	+ * Normalises an SFCC `c_sizeGuide` value to a Contentful entry key segment.
829	+ *
830	+ * SFCC stores size guide keys with a trailing numeric variant suffix and hyphens
831	+ * (e.g. `"clothing-op-4"`). Contentful entry keys use underscores and no suffix
832	+ * (e.g. `"clothing_op"`). This function strips the trailing `-{digits}` and
833	+ * converts the remaining hyphens to underscores.
834	+ */
835	+export const normaliseKey = (key: string): string => key.replace(/-\d+$/, '').replace(/-/g, '_');
836	+
837	+/**
838	+ * Resolves a Contentful `sizeGuide` entry for the given SFCC `c_sizeGuide` key and locale.
839	+ *
840	+ * Resolution order:
841	+ * 1. `size-guide__{key}__{locale}` — locale-specific override
842	+ * 2. `size-guide__{key}` — default fallback
843	+ * 3. `null` — guide section hidden silently
844	+ *
845	+ * All `sizeGuide` fields are `localized: false`, so the Contentful fetch always uses
846	+ * `CONTENTFUL_FALLBACK_LOCALE` to avoid unnecessary re-fetches on locale change.
847	+ * The SFCC locale is used only for constructing the locale-specific key.
848	+ *
849	+ * @returns The matched entry, or `null` when no match is found or `sizeGuideKey` is absent.
850	+ */
851	+export const useSizeGuide = (
852	+  sizeGuideKey: string | undefined,
853	+  locale: string,
854	+): { sizeGuide: SizeGuideEntry | null; isLoading: boolean } => {
855	+  // All sizeGuide fields are localized:false — fetch with fixed locale to avoid re-fetches.
856	+  // Disabled when there is no key so products without a size guide skip the Contentful fetch.
857	+  const { data: entries, isLoading } = useContentfulEntries<SizeGuideEntry>(
858	+    'sizeGuide',
859	+    false,
860	+    CONTENTFUL_FALLBACK_LOCALE,
861	+    !!sizeGuideKey,
862	+  );
863	+
864	+  const sizeGuide = useMemo(() => {
865	+    if (!sizeGuideKey || !entries) return null;
866	+    const normalisedKey = normaliseKey(sizeGuideKey);
867	+    // SFCC sends IETF locales with hyphens (e.g. 'en-AU'); Contentful entry keys and
868	+    // locales[] use underscores ('en_AU') per the sizeGuide key regex and locales validation.
869	+    const canonicalLocale = locale.replace('-', '_');
870	+    const localeKey = `size-guide__${normalisedKey}__${canonicalLocale}`;
871	+    const defaultKey = `size-guide__${normalisedKey}`;
872	+    return (
873	+      entries.find((e) => e.fields.key === localeKey) ??
874	+      entries.find(
875	+        (e) => e.fields.key.startsWith(`${defaultKey}__`) && (e.fields.locales?.includes(canonicalLocale) ?? false),
876	+      ) ??
877	+      entries.find((e) => e.fields.key === defaultKey) ??
878	+      null
879	+    );
880	+  }, [entries, sizeGuideKey, locale]);
881	+
882	+  return { sizeGuide, isLoading };
883	+};
